#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static void radix_pass(uint64_t *src, uint64_t *dst, long long n, int shift){
    long long cnt[256];
    memset(cnt,0,sizeof(cnt));
    for(long long i=0;i<n;i++) cnt[(src[i]>>shift)&255]++;
    long long pos[257], s=0;
    for(int b=0;b<256;b++){ pos[b]=s; s+=cnt[b]; }
    for(long long i=0;i<n;i++){
        int b=(int)((src[i]>>shift)&255);
        dst[pos[b]++]=src[i];
    }
}

int main(void){
    int n;
    if(scanf("%d",&n)!=1) return 0;
    int *X=malloc(sizeof(int)*n), *Y=malloc(sizeof(int)*n);
    for(int i=0;i<n;i++) scanf("%d %d",&X[i],&Y[i]);

    long long ne=(long long)n*n; /* (n-1)*n tent->tent edges + n palace->tent edges */
    uint64_t *E=malloc(sizeof(uint64_t)*ne);
    uint64_t *T=malloc(sizeof(uint64_t)*ne);

    long long idx=0;
    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++){
            if(i==j) continue;
            long long dx=X[i]-X[j], dy=Y[i]-Y[j];
            uint64_t d2=(uint64_t)(dx*dx+dy*dy); /* < 2^30 */
            E[idx++]=(d2<<22)|((uint64_t)i<<11)|(uint64_t)j;
        }
    }
    for(int j=0;j<n;j++){
        long long dx=X[j], dy=Y[j];
        uint64_t d2=(uint64_t)(dx*dx+dy*dy);
        E[idx++]=(d2<<22)|((uint64_t)n<<11)|(uint64_t)j; /* from palace (node n) */
    }

    uint64_t *src=E,*dst=T,*sw;
    for(int b=2;b<=6;b++){ /* squared distance occupies bytes 2..6 of the packed value */
        radix_pass(src,dst,ne,8*b);
        sw=src; src=dst; dst=sw;
    }
    uint64_t *sorted=src;

    int *best_in=calloc(n,sizeof(int)); /* palace has no incoming edges */
    int *vals=malloc(sizeof(int)*ne);
    int ans=0;

    long long i=ne-1;
    while(i>=0){
        uint64_t d=sorted[i]>>22;
        long long lo=i;
        while(lo>0 && (sorted[lo-1]>>22)==d) lo--;
        /* compute values for this length-group before allowing them as incoming edges */
        for(long long k=i;k>=lo;k--){
            int u=(int)((sorted[k]>>11)&2047);
            int val=1+best_in[u];
            vals[k]=val;
            if(val>ans) ans=val;
        }
        for(long long k=i;k>=lo;k--){
            int v=(int)(sorted[k]&2047);
            if(vals[k]>best_in[v]) best_in[v]=vals[k];
        }
        i=lo-1;
    }

    printf("%d\n",ans);
    free(vals); free(best_in); free(E); free(T); free(X); free(Y);
    return 0;
}
